import { build } from 'esbuild';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const entry = require.resolve('@mintlify/editor/converter');

await build({
  entryPoints: [entry],
  outfile: 'bin/vendor/converter.js',
  bundle: true,
  format: 'esm',
  platform: 'node',
  target: 'node18',
  external: [
    '@mintlify/common',
    '@mintlify/validation',
    'js-yaml',
    'mdast-util-*',
    'prosemirror-*',
    'remark*',
    'unified',
    'unist-util-*',
    'yaml',
    'zod',
  ],
});
